function newsDefinition(kind){return kind==='news'?{key:'news:default',endpoint:'Berita/GetBerita?limit=8',title:'Siaran Pers Kementerian',pageTitle:'Berita'}:kind==='announcements'?{key:'announcements:umum',endpoint:'Pengumuman/GetPengumuman?limit=5',title:'Pengumuman',pageTitle:'Pengumuman'}:null;}
function newsItem(item){return !!item&&typeof item==='object'&&!Array.isArray(item)&&['id','title','category','banner','url'].every(key=>item[key]==null||typeof item[key]==='string');}
function newsRows(response){if(response?.status!==200)return null;let body=response.data;if(typeof body==='string'){try{body=JSON.parse(body);}catch{return null;}}return body&&typeof body==='object'&&!Array.isArray(body)&&Array.isArray(body.message)&&body.message.every(newsItem)?body.message:null;}
function newsUrl(value){if(typeof value!=='string'||!value||/[\u0000-\u001f\u007f]/.test(value))return null;try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password?url.href:null;}catch{return null;}}
