function newsViewActive(kind){return route==='dashboard'||route===kind&&(kind!=='announcements'||!flowTab||flowTab==='umum');}
function resetNewsNavigation(){for(const key of ['news:default','announcements:umum']){const owner=flowResults.get(key);if(owner?.newsFeed){owner.request=null;owner.loading=false;owner.scheduled=false;owner.attempted=false;}}}
function newsCardsView(kind,owner){if(owner.loading&&!owner.rows?.length)return `<div class="news-strip" aria-label="Memuat ${esc(newsDefinition(kind).title)}" aria-busy="true">${Array.from({length:4},()=>'<div class="news-card news-skeleton" aria-hidden="true"><span></span><i></i><i></i></div>').join('')}</div>`;if(!owner.rows?.length)return `<p class="news-empty">${owner.error?'Informasi belum dapat dimuat.':'Belum ada informasi yang ditampilkan.'}</p>`;return `<div class="news-strip" aria-label="${esc(newsDefinition(kind).title)}">${owner.rows.map(item=>{const url=newsUrl(item.url),banner=newsUrl(item.banner),content=`<span class="news-banner">${icon('document',28)}${banner?`<img data-news-banner src="${esc(banner)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer">`:''}</span><span class="news-title">${esc(item.title??'')}</span>`;return url?`<a class="news-card" href="${esc(url)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer" aria-label="${esc(item.title||'Buka informasi')} — buka tab baru">${content}</a>`:`<button type="button" class="news-card" disabled aria-label="${esc(item.title||'Informasi')} — tautan belum tersedia">${content}</button>`;}).join('')}</div>`;}
function newsFeedSection(kind,standalone=false){const def=newsDefinition(kind),owner=getNewsState(kind),op=state.operations.find(op=>op.endpoint===def.endpoint&&ready(op)&&!write(op)),available=!!op&&state.connection.configured&&!state.loading;if(available&&!owner.rows?.length&&!owner.attempted&&!owner.scheduled){owner.scheduled=true;const epoch=sessionEpoch;queueMicrotask(()=>{if(flowResults.get(def.key)!==owner||epoch!==sessionEpoch)return;owner.scheduled=false;if(newsViewActive(kind)&&!owner.attempted)loadNewsFeed(kind);});}return `<section class="panel news-feed" data-news-feed="${kind}" aria-labelledby="news-heading-${kind}"><div class="section-heading"><h2 id="news-heading-${kind}">${def.title}</h2><div class="news-actions">${!standalone?`<a class="text-link" href="#/${kind}">Lihat semua ${icon('arrow',14)}</a>`:''}<button class="text-button" data-action="news-reload" data-kind="${kind}" ${!available||owner.loading?'disabled':''}>${icon('refresh',15)} ${owner.loading?'Memuat…':'Muat ulang'}</button></div></div>${owner.error?notice(esc(owner.error),'error'):''}${!state.connection.configured?notice(esc(state.connection.reason||'Koneksi belum dikonfigurasi.')):''}${newsCardsView(kind,owner)}${standalone?'<p class="news-link-note">Artikel dibuka di tab baru melalui tautan dari layanan.</p>':''}</section>`;}
function newsFeedPage(kind){const tabs=kind==='announcements'?`<div class="service-tabs" role="tablist" aria-label="Jenis Pengumuman">${flowDefinitions.announcements.tabs.map(tab=>`<button role="tab" aria-selected="${tab.id==='umum'}" class="${tab.id==='umum'?'active':''}" data-action="flow-tab" data-id="${tab.id}">${tab.label}</button>`).join('')}</div>`:'';return `${head('SENTUH TANAHKU',newsDefinition(kind).pageTitle,kind==='news'?'Siaran pers dan informasi dari Kementerian ATR/BPN.':'Pengumuman terkini dari layanan pertanahan.')}${tabs}${newsFeedSection(kind,true)}`;}
async function loadNewsFeed(kind,refresh=false){const def=newsDefinition(kind);if(!def||!newsViewActive(kind))return;const owner=getNewsState(kind),op=state.operations.find(op=>op.endpoint===def.endpoint&&ready(op)&&!write(op));if(!op||!state.connection.configured||state.loading||owner.loading||owner.rows?.length&&!refresh)return;const request={},epoch=sessionEpoch,view=route;owner.loading=true;owner.attempted=true;owner.scheduled=false;owner.request=request;owner.error='';const current=()=>route===view&&newsViewActive(kind)&&flowResults.get(def.key)===owner&&owner.request===request&&epoch===sessionEpoch;render();try{const reply=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{}}});if(!current())return;const rows=newsRows(reply.result);if(!rows)throw new Error('Respons informasi belum sesuai format layanan. Coba muat ulang.');owner.rows=rows;state.results.set(op.id,reply.result);record(def.pageTitle,'success',`HTTP ${reply.result.status} · ${rows.length} informasi diterima`);}catch(error){if(!current())return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);return;}owner.error=error.message;record(def.pageTitle,'error',`${error.code||'ERROR'} · ${error.message}`);}finally{if(current()){owner.loading=false;owner.request=null;render();}}}
