    if(['not_sent','unknown'].includes(delivery))error.delivery=delivery;
    if(typeof details?.uploadAccepted==='boolean')error.uploadAccepted=details.uploadAccepted;
    if(['not_sent','unknown','confirmed'].includes(details?.activityDelivery))error.activityDelivery=details.activityDelivery;
