function field(f,i){const locked=f.source==='constant'||f.source==='session';const required=f.clientRequired?'required':'';const value=f.source==='session'?'Dari sesi akun':f.default??'';let control;if(f.type==='file')control=`<input id="param-${i}" name="${esc(f.path)}" type="file" ${required} ${f.accept?`accept="${esc(f.accept)}"`:''}>`;else if(f.type==='boolean')control=`<select id="param-${i}" name="${esc(f.path)}" ${required} ${locked?'disabled':''}><option value="">Tidak diisi</option><option value="true" ${value===true?'selected':''}>Ya (true)</option><option value="false" ${value===false?'selected':''}>Tidak (false)</option></select>`;else control=`<input id="param-${i}" name="${esc(f.path)}" type="${/password/i.test(f.path)?'password':['number','integer'].includes(f.type)&&!locked?'number':'text'}" ${['number','integer'].includes(f.type)?'step="any"':''} value="${esc(value)}" ${required} ${locked?'readonly':''} autocomplete="off" placeholder="${esc(f.placeholder||(f.hideType?f.label:f.path))}">`;return `<label class="parameter-field"><span>${esc(f.label||f.path)}${required?'<b class="required">*</b>':''}${f.hideType?'':`<code>${esc(f.type)}</code>`}</span>${control}<small>${esc(f.source==='session'?'Diambil dari akun yang aktif.':f.source==='constant'?'Nilai tetap sesuai kontrak client.':f.description||'')}${f.maxBytes?` · Maksimum ${(f.maxBytes/1024/1024).toFixed(0)} MB`:''}</small></label>`;}
function operation(o){const fields=o.fields||[],complex=fields.some(f=>f.source==='input'&&f.type!=='file'&&(/[.\[\]]/.test(f.path)||['object','array','unknown'].includes(f.type)));const can=ready(o)&&state.connection.configured&&(!needsAuth(o)||state.authenticated);const reason=!ready(o)?o.reason:!state.connection.configured?state.connection.reason:needsAuth(o)&&!state.authenticated?'Masuk ke akun untuk menguji layanan ini.':'';const point=state.points.find(p=>p.id===state.selectedPoint);return `<button class="back-link" data-action="back">← Kembali ke layanan</button>${head(esc(o.group).toUpperCase(),esc(o.label),'Lengkapi parameter, tinjau request, lalu jalankan pengujian.',badge(status(o),ready(o)?'success':'warning'))}<div class="operation-layout"><section class="panel"><div class="section-heading"><h2>Data permintaan</h2>${badge(write(o)?'Pengiriman data':'Pembacaan data',write(o)?'warning':'neutral')}</div>${reason?notice(esc(reason)):''}<form id="operation-form" data-id="${esc(o.id)}" data-complex="${complex}">${complex?`<label>Data parameter (JSON)<textarea class="json-editor" name="__json" rows="12" spellcheck="false" placeholder="{}">{}</textarea><small>Gunakan nama field sesuai kontrak di bawah. Nilai tidak diisi otomatis.</small></label>`:`<div class="parameter-grid">${fields.filter(f=>f.type!=='file').map(field).join('')}</div>`}${fields.filter(f=>f.type==='file').map((f,i)=>field(f,500+i)).join('')}${!fields.length?'<p class="muted">Tidak ada parameter eksplisit yang perlu diisi.</p>':''}<div id="operation-error" class="inline-error" role="alert"></div><div class="form-actions"><span>${icon('shield',15)} Periksa parameter sebelum menjalankan.</span><button class="button" type="submit" ${can?'':'disabled'}>Tinjau permintaan ${icon('arrow',16)}</button></div></form><details class="contract-details" ${!ready(o)?'open':''}><summary>${icon('code',17)} Parameter & detail teknis</summary><div class="endpoint-row">${badge(o.method)}<code>${esc(o.endpoint)}</code></div><div class="table-scroll"><table><thead><tr><th>Field</th><th>Tipe client</th><th>Wajib server</th></tr></thead><tbody>${fields.map(f=>`<tr><td><code>${esc(f.path)}</code></td><td>${esc(f.type)}</td><td>${f.required==='unknown'?'Belum diketahui':esc(f.required)}</td></tr>`).join('')}</tbody></table></div><p>${esc(o.coordinateNotice||'Struktur berasal dari audit client. Validasi dan penerimaan server perlu dibuktikan melalui pengujian.')}</p></details></section><aside class="result-side"><section class="panel"><div class="section-heading"><h2>Hasil layanan</h2>${state.results.has(o.id)?badge(`HTTP ${state.results.get(o.id).status}`,'success'):badge('Belum dijalankan')}</div>${state.results.has(o.id)?result(state.results.get(o.id)):empty('Menunggu pengujian','Respons server tampil setelah Anda menjalankan permintaan.','wifi')}</section><div class="small-note">${icon('info',17)}<p>Hasil hanya berasal dari request yang Anda jalankan. Data akun tidak diisi dengan contoh.</p></div></aside></div>`;}
