function homeMediaCurrent(owner){return !!owner&&flowResults.get('home:media')===owner&&owner.epoch===sessionEpoch&&route==='dashboard';}
function homeMediaOwner(){
 let owner=flowResults.get('home:media');if(owner)return owner;
 owner={epoch:sessionEpoch,host:null};
 owner.host=createHomeMediaHost({document,isCurrent:()=>homeMediaCurrent(owner),read:async kind=>{
  if(!homeMediaCurrent(owner)){const error=new Error('Halaman informasi telah berubah.');error.code='STALE_CONTEXT';throw error;}
  if(state.loading||!state.connection.configured){const error=new Error('Koneksi informasi belum siap.');error.code='NOT_READY';throw error;}
  const id=HOME_MEDIA_OPERATIONS[kind],op=state.operations.find(item=>item.id===id&&ready(item)&&!write(item));
  if(!op){const error=new Error('Informasi ini belum tersedia. Coba periksa koneksi kembali.');error.code='NOT_READY';throw error;}
  if(needsAuth(op)&&!state.authenticated){const error=new Error('Masuk ke akun untuk memuat informasi ini.');error.code='AUTH_REQUIRED';throw error;}
  return (await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{}}})).result;
 },onAuthError:error=>{
  if(!homeMediaCurrent(owner)||!state.authenticated||!['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error?.code))return;
  sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);
 }});flowResults.set('home:media',owner);return owner;
}
function homeMediaSection(){
 if(state.loading)return '<div class="home-media-placeholder" aria-busy="true" role="status">Memuat informasi Beranda…</div>';
 if(!state.connection.configured||!state.operations.length)return '<section class="home-media-section"><h2>Informasi Beranda</h2><p class="home-media-feedback">Informasi belum dapat dimuat. Periksa koneksi lalu coba lagi.</p><button type="button" class="text-button" data-action="refresh">Periksa koneksi</button></section>';
 return homeMediaOwner().host.view();
}
function homeMediaPaint(){if(route!=='dashboard'||state.loading||!state.connection.configured||!state.operations.length)return;const outlet=$('#main [data-home-media]');if(outlet)homeMediaOwner().host.mount(outlet);}

function menuTiles(){return serviceMenus.map(m=>`<a class="official-menu-tile" href="#/${m.route}"><span><img src="assets/icons/${esc(m.asset)}" alt=""></span><strong>${esc(m.label)}</strong></a>`).join('');}
function dashboard(){return `<div class="home-heading"><div><span class="eyebrow">SENTUH TANAHKU</span><h1>${state.authenticated?`Halo, ${esc(state.user?.username||'Sobat ATR/BPN')}.`:'Halo, Sobat ATR/BPN.'}</h1><p>Akses informasi pertanahan dan layanan Anda.</p></div>${state.authenticated?badge('Akun terhubung','success'):`<a class="button" href="#/account">${icon('user',16)} Masuk</a>`}</div><div class="home-layout"><div>${homeMediaSection()}<section class="panel laci-panel"><div class="section-heading"><h2>Laci</h2><span class="subtle">Dokumen & berkas Anda</span></div><div class="laci-grid">${[['certificates','Sertipikatku','sertipikatku.svg'],['akta','Aktaku','akta.svg'],['files','Berkasku','berkasku.svg']].map(([r,t,a])=>`<a href="#/${r}"><img src="assets/icons/${a}" alt=""><strong>${t}</strong>${!state.authenticated?icon('lock',12):''}</a>`).join('')}</div></section><section class="panel official-services"><div class="section-heading"><h2>Layanan Pertanahan</h2><a class="text-link" href="#/services">Lihat semua ${icon('arrow',14)}</a></div><div class="official-menu-grid">${menuTiles()}</div></section></div><aside class="home-aside"><section class="panel favorite-office"><span class="square-icon mint">${icon('pin',22)}</span><h2>Kantor Pertanahan</h2><p>Cari kantor pertanahan untuk informasi layanan Anda.</p><a class="button secondary full" href="#/office">Cari kantor ${icon('search',16)}</a></section><section class="panel home-news"><div class="section-heading"><h2>Informasi</h2></div>${informationMenus.map(m=>`<a href="#/${m.route}"><img src="assets/icons/${m.asset}" alt=""><span><strong>${m.label}</strong></span>${icon('chevron',16)}</a>`).join('')}</section><section class="comparison-promo"><span>${icon('pin',22)}</span><div><h3>Periksa selisih koordinat</h3><p>Bandingkan titik referensi dengan hasil pengukuran secara lokal.</p><a href="#/coordinates" class="text-link">Buka perbandingan ${icon('arrow',14)}</a></div></section></aside></div>${newsFeedSection('news')}${newsFeedSection('announcements')}<div class="reconstruction-note">${icon('info',15)}<span>Nama menu dan aset mengikuti APK. Susunan layar browser disesuaikan; kesetaraan visual dan seluruh alur Android belum terverifikasi.</span></div>`;}
function serviceDirectory(){return `${head('LAYANAN PERTANAHAN','Layanan Sentuh Tanahku','Pilih layanan yang ingin Anda gunakan.')}<div class="service-directory">${serviceMenus.map(m=>`<a href="#/${m.route}" class="service-directory-card"><img src="assets/icons/${esc(m.asset)}" alt=""><div><h2>${esc(m.label)}</h2><p>${esc(m.description)}</p></div>${icon('chevron',19)}</a>`).join('')}</div><div class="secondary-services">${[['collections','Koleksi','files.svg'],['office','Kantor Pertanahan','company.svg'],['news','Berita','newspaper.svg']].map(([r,t,a])=>`<a class="document-shortcut" href="#/${r}"><img src="assets/icons/${a}" alt=""><div><strong>${t}</strong><span>Buka layanan</span></div>${icon('chevron',16)}</a>`).join('')}</div>`;}
function currentFlow(){const def=flowDefinitions[route];if(!def)return null;if(route==='partners')return partnerFlowContext(def);const tab=def.tabs?(def.tabs.find(t=>t.id===flowTab)||def.tabs[0]):def;return {def,tab,key:`${route}:${tab.id||'default'}`,op:state.operations.find(o=>o.endpoint===tab.endpoint&&ready(o))||state.operations.find(o=>o.endpoint===tab.endpoint)};}
function nativeVerificationStatus(response){const body=response?.data;if(!Number.isInteger(response?.status)||response.status<200||response.status>=300||!body||typeof body!=='object'||Array.isArray(body))return null;if(body.error!=null&&typeof body.error!=='boolean'||body.message!=null&&typeof body.message!=='string'||body.data!=null&&typeof body.data!=='string')return null;return {error:body.error??null,message:body.message??null,data:body.data??null};}
function nativeOfficeEnvelope(response,valid){const body=response?.data;if(!Number.isInteger(response?.status)||response.status<200||response.status>=300||!body||typeof body!=='object'||Array.isArray(body)||typeof body.error!=='boolean'||body.message!=null&&typeof body.message!=='string')return null;for(const key of ['totalRecords','resultsCount','pageSize','pageNumber'])if(body[key]!=null&&!Number.isInteger(body[key]))return null;const rows=body.data??[];if(!Array.isArray(rows)||!rows.every(valid))return null;return body.error?[]:rows;}
function nearbyOfficeItem(item){return !!item&&typeof item==='object'&&!Array.isArray(item)&&['kantorId','namaKantor','alamat'].every(key=>typeof item[key]==='string')&&['latitude','longitude','jarak'].every(key=>typeof item[key]==='number'&&Number.isFinite(item[key]))&&['statusAntrian','statusPeralihanEl','statusKiosk'].every(key=>Number.isInteger(item[key]));}
function nearbyOfficeRows(response){return nativeOfficeEnvelope(response,nearbyOfficeItem);}
function officeCalendarItem(item){return !!item&&typeof item==='object'&&!Array.isArray(item)&&['tanggal','keterangan','tipe','tipeLiburId'].every(key=>item[key]==null||typeof item[key]==='string');}
function officeCalendarRows(response){return nativeOfficeEnvelope(response,officeCalendarItem);}
function officeEntries(owner){const query=owner.query.toLowerCase(),filters=[[1,'statusPeralihanEl'],[2,'statusAntrian'],[3,'statusKiosk']];return (owner.rows||[]).map((item,index)=>({item,index})).filter(({item})=>item.namaKantor.toLowerCase().includes(query)&&filters.every(([id,key])=>!owner.filters.includes(id)||item[key]===1));}
function getOfficeState(){let owner=flowResults.get('office:nearby');if(!owner){const now=new Date();owner={rows:null,query:'',filters:[],position:null,locationBusy:false,loading:false,error:'',request:null,selected:null,detailOpen:false,calendar:{year:now.getFullYear(),month:now.getMonth(),rows:null,loading:false,error:'',request:null,office:null,loadedYear:null}};flowResults.set('office:nearby',owner);}return owner;}
function officeFiltersView(owner){return `<div class="office-filters" role="group" aria-label="Fasilitas kantor">${[[1,'Peralihan Elektronik'],[2,'Antrian Daring'],[3,'Anjungan Pencetakan Sertipikat']].map(([id,label])=>`<button type="button" class="button secondary small ${owner.filters.includes(id)?'selected':''}" data-action="office-filter" data-index="${id}" aria-pressed="${owner.filters.includes(id)}">${label}</button>`).join('')}</div>`;}
function officeFeaturesView(item){return `<ul class="office-features">${[['statusPeralihanEl','Peralihan Elektronik'],['statusAntrian','Antrian Daring'],['statusKiosk','Anjungan Pencetakan Sertipikat']].map(([key,label])=>`<li class="${item[key]===1?'available':'unavailable'}">${icon(item[key]===1?'check':'close',16)}<span>${label}</span><span class="sr-only">${item[key]===1?' tersedia':' belum tersedia'}</span></li>`).join('')}</ul>`;}
function officeListView(owner){const entries=officeEntries(owner);return `<section class="panel office-list-panel"><label class="parameter-field" for="office-query"><span>Cari nama kantor</span><input id="office-query" type="search" placeholder="cari nama kantor" autocomplete="off" value="${esc(owner.query)}"></label>${officeFiltersView(owner)}${entries.length?`<div class="office-list" aria-label="Daftar Kantor Pertanahan">${entries.map(({item,index})=>`<button type="button" class="office-card ${owner.selected===item?'selected':''}" data-action="office-select" data-index="${index}"><span class="office-card-icon"><img src="assets/icons/company.svg" width="25" height="25" alt=""></span><span class="office-card-content"><strong>${esc(item.namaKantor)}</strong><span>${esc(item.alamat)}</span><small>${esc(item.jarak)} Km</small><span class="office-row-features">${[['statusPeralihanEl','Peralihan Elektronik'],['statusAntrian','Antrian Daring'],['statusKiosk','Anjungan Pencetakan Sertipikat']].map(([key,label])=>`<span class="${item[key]===1?'available':'unavailable'}" title="${label}" aria-label="${label}: ${item[key]===1?'tersedia':'belum tersedia'}">${icon(item[key]===1?'check':'close',14)}<span>${label}</span></span>`).join('')}</span></span>${icon('arrow',16)}</button>`).join('')}</div>`:empty('Kantor tidak ditemukan','Coba nama atau pilihan fasilitas lainnya.','search')}</section>`;}
function officeSelectedView(owner){const item=owner.selected;if(!item||!owner.detailOpen)return '';return `<section class="panel office-selected" role="region" aria-label="Kantor yang dipilih"><div class="office-selected-heading"><h2>${esc(item.namaKantor)}</h2><button type="button" class="icon-button" data-action="office-close" aria-label="Tutup informasi kantor">${icon('close')}</button></div>${officeFeaturesView(item)}</section>`;}
function renderOffice(){if(['office','officecalendar'].includes(route))render();}
function officeOperation(endpoint){return state.operations.find(op=>op.endpoint===endpoint&&ready(op)&&!write(op));}
function officeLocationControls(owner){const op=officeOperation('kantornearby/getkantornearby'),busy=owner.locationBusy||owner.loading;return `<section class="panel office-location-controls"><div><h2>Kantor di sekitar lokasi Anda</h2><p>Gunakan lokasi perangkat untuk mencari kantor. Posisi dikirim ke layanan pencarian kantor ATR/BPN.</p></div><button type="button" class="button" data-action="office-location" ${busy||!op||!state.connection.configured?'disabled':''}>${icon('pin',16)} ${owner.locationBusy?'Membaca lokasi…':owner.loading?'Mencari kantor…':owner.rows?'Perbarui lokasi & kantor':'Gunakan lokasi perangkat'}</button>${owner.position&&!busy?'<button type="button" class="text-button" data-action="office-reload">Muat ulang daftar kantor</button>':''}${!op?notice('Pencarian kantor terdekat belum siap pada build ini.'):''}${!state.connection.configured?notice(esc(state.connection.reason||'Koneksi belum siap.')):''}${owner.error?notice(esc(owner.error),'error'):''}</section>`;}
function officePage(){const owner=getOfficeState();const map=officeMapView(owner);return `${head('SENTUH TANAHKU','Kantor Pertanahan','Temukan kantor pertanahan dan fasilitas layanannya.')}${officeLocationControls(owner)}${map}${owner.rows?officeListView(owner):!owner.loading&&!owner.locationBusy?`<section class="panel">${empty('Cari kantor terdekat','Izinkan lokasi perangkat untuk memuat daftar kantor dari layanan.','pin')}</section>`:''}`;}
function officeMonthName(month){return ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'][month]||'';}
function parseOfficeCalendarDate(value){if(typeof value!=='string'||!value)return null;if(value.includes('T')){if(!/^\d{4}-\d{2}-\d{2}T/.test(value))return null;const date=new Date(value);if(!Number.isFinite(date.getTime()))return null;const utc=/(?:Z|[+-]\d{2}(?::?\d{2})?)$/i.test(value);return {year:utc?date.getUTCFullYear():date.getFullYear(),month:utc?date.getUTCMonth():date.getMonth(),day:utc?date.getUTCDate():date.getDate(),time:date.getTime()};}const match=/^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(value);if(!match)return null;const year=Number(match[1]),month=Number(match[2])-1,day=Number(match[3]),date=new Date(0);date.setHours(0,0,0,0);date.setFullYear(year,month,day);if(date.getFullYear()!==year||date.getMonth()!==month||date.getDate()!==day)return null;return {year,month,day,time:date.getTime()};}
function officeCalendarEvents(rows,year,month){return (rows||[]).map((item,index)=>({item,index,date:parseOfficeCalendarDate(item.tanggal)})).filter(entry=>entry.item.tipeLiburId==='2'&&entry.date?.year===year&&entry.date.month===month).sort((a,b)=>a.date.time-b.date.time||a.index-b.index);}
function officeCalendarEventsView(calendar){const entries=officeCalendarEvents(calendar.rows,calendar.year,calendar.month);return `<section class="office-calendar-events">${entries.length?`<ul>${entries.map(({item,date})=>`<li><strong>${date.day} ${officeMonthName(date.month)}</strong><span>${esc(item.keterangan??'Tidak ada keterangan')}</span></li>`).join('')}</ul>`:`<p>${calendar.rows?.length?'Tidak ada data kalender untuk bulan ini':'Tidak ada data kalender tersedia'}</p>`}</section>`;}
function officeCalendarGrid(calendar){const first=new Date(calendar.year,calendar.month,1),offset=(first.getDay()+6)%7,count=new Date(calendar.year,calendar.month+1,0).getDate(),cells=Math.ceil((offset+count)/7)*7,now=new Date(),marked=new Set((calendar.rows||[]).map(item=>parseOfficeCalendarDate(item.tanggal)).filter(date=>date?.year===calendar.year&&date.month===calendar.month).map(date=>date.day));let body='';for(let row=0;row<cells/7;row++){body+='<tr>';for(let column=0;column<7;column++){const date=new Date(calendar.year,calendar.month,row*7+column-offset+1),inside=date.getMonth()===calendar.month,today=date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()&&date.getDate()===now.getDate();body+=`<td class="${inside?'':'outside'} ${today?'today':inside&&marked.has(date.getDate())?'event-day':''}" ${today?'aria-current="date"':''}><span>${date.getDate()}</span></td>`;}body+='</tr>';}return `<table class="office-calendar-grid" aria-label="Kalender ${officeMonthName(calendar.month)} ${calendar.year}"><thead><tr>${['Sen','Sel','Rab','Kam','Jum','Sab','Mgg'].map((label,index)=>`<th scope="col" class="${index>4?'weekend':''}">${label}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table>`;}
function officeCalendarPage(){const owner=getOfficeState(),calendar=owner.calendar,now=new Date(),op=officeOperation('KantorNearby/GetCalendar');if(calendar.year!==now.getFullYear()||calendar.month<now.getMonth()){Object.assign(calendar,{year:now.getFullYear(),month:now.getMonth(),rows:null,loadedYear:null,request:null,loading:false,error:''});}if(owner.rows?.length&&!owner.selected)owner.selected=owner.rows[0];const usable=owner.selected&&typeof owner.selected.kantorId==='string'&&owner.selected.kantorId.trim(),blocked=!op||!state.connection.configured||op&&needsAuth(op)&&!state.authenticated;if(owner.rows&&usable&&!blocked&&!calendar.loading&&!calendar.error&&!calendar.scheduled&&(calendar.office!==owner.selected||calendar.loadedYear!==calendar.year)){calendar.scheduled=true;queueMicrotask(()=>{calendar.scheduled=false;if(route==='officecalendar'&&flowResults.get('office:nearby')===owner&&owner.calendar===calendar)loadOfficeCalendar();});}return `${head('SENTUH TANAHKU','Kalender Kantor Pertanahan','Kalender Jadwal Pelayanan & Hari Libur')}${officeLocationControls(owner)}${owner.rows?`<section class="panel office-calendar-panel"><label class="parameter-field" for="office-calendar-select"><span>Kantor Pertanahan</span><select id="office-calendar-select" ${owner.loading?'disabled':''}><option value="">${owner.loading?'Memuat data..':'Pilih Kantor Pertanahan'}</option>${owner.rows.map((item,index)=>`<option value="${index}" ${owner.selected===item?'selected':''} ${item.kantorId.trim()?'':'disabled'}>${esc(item.namaKantor)}</option>`).join('')}</select></label><div class="office-calendar-heading"><button type="button" class="icon-button" data-action="office-month" data-index="-1" aria-label="Bulan sebelumnya" ${calendar.month<=now.getMonth()?'disabled':''}>${icon('arrow',18)}</button><h2>${officeMonthName(calendar.month).slice(0,3)} ${calendar.year}</h2><button type="button" class="icon-button" data-action="office-month" data-index="1" aria-label="Bulan berikutnya" ${calendar.month>=11?'disabled':''}>${icon('arrow',18)}</button></div>${officeCalendarGrid(calendar)}${blocked?notice(op&&needsAuth(op)&&!state.authenticated?'Masuk ke akun untuk membaca kalender layanan.':'Pembacaan kalender belum siap pada build ini.'):!usable?notice('Pilih kantor dengan referensi yang tersedia.'):`${calendar.loading?'<p role="status">Memuat kalender layanan…</p>':''}${calendar.error?`${notice(esc(calendar.error),'error')}<button type="button" class="button secondary" data-action="office-calendar-reload">Coba lagi kalender</button>`:''}${calendar.rows?officeCalendarEventsView(calendar):''}`}${calendar.rows?'<button type="button" class="text-button" data-action="office-calendar-reload">Perbarui kalender</button>':''}</section>`:''}`;}
async function selectCalendarOffice(index){if(route!=='officecalendar'||!Number.isInteger(index)||index<0)return;const owner=getOfficeState();if(!Array.isArray(owner.rows)||!Object.hasOwn(owner.rows,index))return;owner.selected=owner.rows[index];Object.assign(owner.calendar,{office:null,loadedYear:null,rows:null,error:'',request:null,loading:false});renderOffice();await loadOfficeCalendar();}
async function loadOfficeCalendar(){if(route!=='officecalendar')return;const owner=getOfficeState(),calendar=owner.calendar,selected=owner.selected,op=officeOperation('KantorNearby/GetCalendar');if(!op||!state.connection.configured||!selected||!owner.rows?.includes(selected)||typeof selected.kantorId!=='string'||!selected.kantorId.trim()||calendar.loading||needsAuth(op)&&!state.authenticated)return;const epoch=sessionEpoch,request={},year=calendar.year,retain=calendar.office===selected&&calendar.loadedYear===year;calendar.request=request;calendar.loading=true;calendar.error='';if(!retain){calendar.rows=null;calendar.loadedYear=null;}calendar.office=selected;const current=()=>route==='officecalendar'&&flowResults.get('office:nearby')===owner&&owner.calendar===calendar&&calendar.request===request&&owner.selected===selected&&calendar.year===year&&epoch===sessionEpoch;renderOffice();try{const reply=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{kantorId:selected.kantorId,tahun:String(year)}}});if(!current())return;const rows=officeCalendarRows(reply.result);if(!rows)throw new Error('Respons kalender belum dikenali. Coba muat kembali.');calendar.rows=rows;calendar.loadedYear=year;state.results.set(op.id,reply.result);record('Kalender Kantor Pertanahan','success',`HTTP ${reply.result.status} · Kalender diterima`);}catch(error){if(!current())return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);return;}calendar.error=error.message;record('Kalender Kantor Pertanahan','error',`${error.code||'ERROR'} · ${error.message}`);}finally{if(current()){calendar.loading=false;calendar.request=null;renderOffice();}}}
function changeOfficeMonth(delta){if(route!=='officecalendar'||![1,-1].includes(delta))return;const owner=getOfficeState(),calendar=owner.calendar,now=new Date(),month=calendar.month+delta;if(calendar.year!==now.getFullYear()||month<now.getMonth()||month>11)return;calendar.month=month;renderOffice();}
function filterOffices(input){if(route!=='office'||!input?.isConnected)return;const owner=getOfficeState(),start=input.selectionStart,end=input.selectionEnd;owner.query=input.value;renderOffice();const replacement=$('#office-query');replacement?.focus({preventScroll:true});if(replacement&&start!=null&&end!=null)replacement.setSelectionRange(start,end);}
function toggleOfficeFilter(id){if(route!=='office'||![1,2,3].includes(id))return;const owner=getOfficeState();owner.filters=owner.filters.includes(id)?owner.filters.filter(value=>value!==id):[...owner.filters,id];renderOffice();}
function openOfficeItem(index){if(route!=='office'||!Number.isInteger(index)||index<0)return;const owner=getOfficeState();if(!Array.isArray(owner.rows)||!Object.hasOwn(owner.rows,index)||!officeEntries(owner).some(row=>row.index===index))return;if(typeof disposeOfficeMap==='function')disposeOfficeMap(false);owner.selected=owner.rows[index];owner.detailOpen=true;owner.mapCamera=null;renderOffice();if(typeof focusOfficeMapSelection==='function')focusOfficeMapSelection(owner);}
async function requestOfficeLocation(){if(!['office','officecalendar'].includes(route)||!officeOperation('kantornearby/getkantornearby')||!state.connection.configured)return;const owner=getOfficeState();if(owner.locationBusy||owner.loading)return;if(!navigator.geolocation){owner.error='Browser ini belum menyediakan pembacaan lokasi perangkat.';renderOffice();return;}const request={},epoch=sessionEpoch,view=route;owner.request=request;owner.locationBusy=true;owner.error='';const current=()=>route===view&&flowResults.get('office:nearby')===owner&&owner.request===request&&epoch===sessionEpoch;renderOffice();try{const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:20000,maximumAge:0}));if(!current())return;const {latitude,longitude}=position.coords;if(!Number.isFinite(latitude)||!Number.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180)throw new Error('Lokasi perangkat belum valid. Coba kembali.');owner.position={latitude,longitude};owner.locationBusy=false;owner.request=null;await loadNearbyOffices(owner);}catch(error){if(!current())return;owner.error=error.code===1?'Izin lokasi belum diberikan. Izinkan lokasi pada browser, lalu coba kembali.':error.code===3?'Pembacaan lokasi melewati batas waktu. Coba kembali di tempat dengan penerimaan lokasi lebih baik.':error.code===2?'Lokasi perangkat belum tersedia. Periksa layanan lokasi perangkat, lalu coba kembali.':error.message||'Lokasi perangkat belum dapat dibaca.';}finally{if(current()){owner.locationBusy=false;owner.request=null;renderOffice();}}}
async function loadNearbyOffices(owner=getOfficeState()){const op=officeOperation('kantornearby/getkantornearby');if(!['office','officecalendar'].includes(route)||!op||!state.connection.configured||flowResults.get('office:nearby')!==owner||!owner.position||owner.loading)return;const request={},epoch=sessionEpoch,view=route;owner.request=request;owner.loading=true;owner.error='';const current=()=>route===view&&flowResults.get('office:nearby')===owner&&owner.request===request&&epoch===sessionEpoch;renderOffice();try{const reply=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{latitude:owner.position.latitude,longitude:owner.position.longitude,radius:0.1,isKalender:1,limit:null}}});if(!current())return;const rows=nearbyOfficeRows(reply.result);if(!rows)throw new Error('Respons daftar kantor belum dikenali. Coba muat kembali.');const selectedId=owner.selected?.kantorId;owner.rows=rows;owner.selected=rows.find(item=>item.kantorId===selectedId)||null;const calendar=owner.calendar;calendar.request=null;calendar.loading=false;calendar.rows=null;calendar.office=null;calendar.loadedYear=null;calendar.error='';state.results.set(op.id,reply.result);record('Kantor Pertanahan','success',`HTTP ${reply.result.status} · Daftar kantor diterima`);if(view==='officecalendar'){owner.selected??=rows[0]||null;owner.loading=false;await loadOfficeCalendar();}}catch(error){if(!current())return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);return;}owner.error=error.message;record('Kantor Pertanahan','error',`${error.code||'ERROR'} · ${error.message}`);}finally{if(current()){owner.loading=false;owner.request=null;renderOffice();}}}
function nativeVerificationDecision(response,user){const status=nativeVerificationStatus(response);if(!status)return null;if(status.message==='-1'||status.message==='3')return {kind:'methods'};if(!user||typeof user!=='object'||Array.isArray(user)||user.userLevel!=null&&!Number.isSafeInteger(user.userLevel)||user.userLevel===2)return null;if(status.message==='0')return {kind:'status',message:'Permohonan verifikasi akun sedang dalam proses.',first:'Ok',action:null};if(status.message==='1')return {kind:'status',message:'Permohonan verifikasi kamu telah disetujui. Mohon untuk login kembali untuk memperbarui akun kamu.',first:'Batal ',action:'logout'};if(status.message==='2')return {kind:'status',message:'Permohonan verifikasi kamu ditolak. \n'+(status.data??''),first:'Batal ',action:'methods'};return null;}
function verificationDialogCurrent(owner=flowResults.get('verification:dialog-state'),button=null){const modal=$('#modal');return !!owner&&flowResults.get('verification:dialog-state')===owner&&state.authenticated===true&&route==='verification'&&owner.epoch===sessionEpoch&&owner.navigation===detailSequence&&flowResults.get(owner.key)===owner.reader&&owner.reader.response===owner.response&&!owner.reader.loading&&modal.open===true&&modal.querySelector('[data-verification-dialog]')===owner.element&&(!button||button.isConnected!==false&&owner.element.contains(button));}
function dismissVerificationDialog(button=null){const owner=flowResults.get('verification:dialog-state');if(!verificationDialogCurrent(owner,button)||verificationDaringBusy())return;flowResults.delete('verification:dialog-state');$('#modal').close();$('#modal').innerHTML='';}
function verificationMethodView(index){const methods=[{"name":"Daring","image":"verification-ktp.png","alt":"Ilustrasi e-KTP","text":["Cek dulu nih, pastikan e-KTP-mu belum terkait sama akun Sentuh Tanahku lain.","Kalau udah terkait, kamu bisa lepasin tautannya pake akun IKD di menu berikutnya, ya!"]},{"name":"Luring","image":"verification-aps.png","alt":"Anjungan Pencetakan Sertipikat","instructions":["1. Datang ke Anjungan Pencetakan Sertipikat terdekat.","2. Validasi identitas menggunakan e-KTP.","3. Pilih menu Sentuh Tanahku pada layar.","4. Pindai kode QR yang tersedia.","5. Periksa kembali data kamu","6. Ketuk tombol Verifikasi Akun","7. Tunggu proses selesai, lalu akun Kamu berhasil diverifikasi."]},{"name":"IKD","image":"verification-ikd.webp","alt":"Identitas Kependudukan Digital","text":["Pastikan kamu sudah memiliki akun Identitas Kependudukan Digital (IKD) dari Dukcapil.","Jika belum punya, kamu bisa mendaftarkannya di Dukcapil terdekat."]}];if(!Number.isInteger(index)||index<0||index>=methods.length)return '<p class="verification-method-empty">Pilih metode verifikasi untuk melihat petunjuknya.</p>';const method=methods[index];return `<article class="verification-method-panel" aria-label="Verifikasi ${esc(method.name)}"><img class="verification-method-illustration ${index===1?'verification-method-aps':''}" src="assets/profile/${method.image}" alt="${esc(method.alt)}"><h3>Verifikasi ${esc(method.name)}</h3>${method.instructions?`<div class="verification-method-instructions" role="list" aria-label="Langkah verifikasi luring">${method.instructions.map(text=>`<p role="listitem">${esc(text)}</p>`).join('')}</div>`:method.text.map(text=>`<p>${esc(text)}</p>`).join('')}${index===0&&verificationDaringOperation()?'<button type="button" class="button" data-action="verification-daring-start">Mulai Verifikasi</button>':'<p id="verification-method-unavailable" class="verification-method-continuation">Lanjutkan proses verifikasi identitas melalui aplikasi Android Sentuh Tanahku.</p><button type="button" class="button" disabled aria-describedby="verification-method-unavailable">Mulai Verifikasi</button>'}</article>`;}
function verificationMethodsView(selected=null){return `<div class="modal-heading"><h2 id="modal-title">Metode verifikasi</h2></div><section class="modal-body verification-dialog verification-methods" data-verification-dialog><div class="verification-method-tabs" role="group" aria-label="Metode verifikasi">${['Daring','Luring','IKD'].map((name,index)=>`<button type="button" class="button secondary" data-action="verification-method-choice" data-index="${index}" aria-pressed="${selected===index}">${name}</button>`).join('')}</div>${verificationMethodView(selected)}<div class="modal-actions"><button type="button" class="button secondary" data-action="verification-dismiss">Tutup</button></div></section>`;}
function verificationMethodsPaint(owner){if(!verificationDialogCurrent(owner)||owner.stage!=='methods')return;const modal=$('#modal');modal.innerHTML=verificationMethodsView(owner.method);owner.element=modal.querySelector('[data-verification-dialog]');const target=Number.isInteger(owner.method)?`[data-action="verification-method-choice"][data-index="${owner.method}"]`:'[data-action="verification-dismiss"]';modal.querySelector(target)?.focus({preventScroll:true});}
function verificationMethodChoice(index,button){const owner=flowResults.get('verification:dialog-state');if(!verificationDialogCurrent(owner,button)||owner.stage!=='methods'||!Number.isInteger(index)||index<0||index>2||owner.method===index)return;owner.method=index;verificationMethodsPaint(owner);}
function showVerificationMethods(owner=flowResults.get('verification:dialog-state'),button=null){if(!verificationDialogCurrent(owner,button)||!(owner.stage==='methods-pending'||owner.stage==='status'&&owner.action==='methods'))return;owner.stage='methods';owner.method=null;verificationMethodsPaint(owner);}
function showVerificationStatusDialog(reader,key,epoch,navigation){if(route!=='verification'||state.authenticated!==true||epoch!==sessionEpoch||navigation!==detailSequence||flowResults.get(key)!==reader||reader.loading||reader.verificationDialogHandled)return;reader.verificationDialogHandled=true;const decision=nativeVerificationDecision(reader.response,state.user),modal=$('#modal');if(!decision||modal.open)return;const owner={reader,key,epoch,navigation,response:reader.response,element:null,stage:decision.kind==='methods'?'methods-pending':'status',action:decision.action??null};flowResults.set('verification:dialog-state',owner);modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">Status Verifikasi</h2></div><section class="modal-body verification-dialog" data-verification-dialog><p class="verification-dialog-message">${esc(decision.message??'')}</p>${decision.action==='logout'?'<p class="verification-session-note">Logout mengakhiri sesi webapp ini.</p>':''}<div class="modal-actions"><button type="button" class="button secondary" data-action="verification-dismiss">${esc(decision.first??'Tutup')}</button>${decision.action==='logout'?'<button type="button" class="button" data-action="logout" data-verification-logout="true">Logout</button>':decision.action==='methods'?'<button type="button" class="button" data-action="verification-methods">Verifikasi</button>':''}</div></section>`;owner.element=modal.querySelector('[data-verification-dialog]');modal.showModal();if(decision.kind==='methods')showVerificationMethods(owner);else modal.querySelector('[data-action="verification-dismiss"]')?.focus({preventScroll:true});}
function verificationDaringOperation(){return state.authenticated===true&&state.connection.configured&&!state.loading?state.operations.find(op=>op.id===DARING_OPERATION_ID&&ready(op)&&op.method==='POST'&&op.path==='PeruriLivenessSdk/ValidateKTPDataV2'&&op.serviceId==='main'&&op.auth==='session'&&op.encoding==='multipart'&&op.effect==='write'&&op.requiresConfirmation===true):null;}
function verificationDaringBusy(){const owner=flowResults.get('verification:dialog-state');return verificationDialogCurrent(owner)&&owner.stage==='daring-sending';}
function verificationDaringStart(button){const owner=flowResults.get('verification:dialog-state');if(!verificationDialogCurrent(owner,button)||owner.stage!=='methods'||owner.method!==0||!verificationDaringOperation())return;owner.daring??={values:daringValues(),errors:{},problem:'',snapshot:null,request:null};owner.stage='daring-form';verificationDaringPaint(owner);}
function verificationDaringFieldView(field,model){const id='verification-daring-'+field.key,error=model.errors[field.key],date=field.key==='TglLahir',bounds=daringDateBounds();return `<label class="verification-daring-field" for="${id}"><span>${esc(field.label)}</span><input id="${id}" name="${field.key}" data-daring-field="${field.key}" type="${date?'date':'text'}" value="${esc(date?daringDateForInput(model.values[field.key]):model.values[field.key])}" autocomplete="off" ${date?`min="${bounds.min}" max="${bounds.max}"`:''} ${field.key==='Nik'||field.key==='NoHp'?'inputmode="numeric"':''} aria-invalid="${!!error}" aria-describedby="${id}-error"><span class="verification-field-error" id="${id}-error" aria-live="polite">${esc(error??'')}</span></label>`;}
function verificationDaringPaint(owner){if(!verificationDialogCurrent(owner)||!owner.daring||!['daring-form','daring-info','daring-review','daring-sending','daring-otp-boundary'].includes(owner.stage))return;const model=owner.daring,stage=owner.stage,modal=$('#modal');let body;if(stage==='daring-form')body=`<h3>${DARING_COPY.heading}</h3><p>${DARING_COPY.instruction}</p>${model.problem?`<p class="notice error" role="alert">${esc(model.problem)}</p>`:''}<form id="verification-daring-form" novalidate>${DARING_FIELDS.map(field=>verificationDaringFieldView(field,model)).join('')}<div class="modal-actions"><button type="button" class="button secondary" data-action="verification-daring-back">Kembali</button><button type="submit" class="button">${DARING_COPY.continue}</button></div></form>`;else if(stage==='daring-info')body=`<h3>Info</h3><p class="verification-dialog-message">${esc(model.info??'')}</p><div class="modal-actions"><button type="button" class="button" data-action="verification-daring-ok">Ok</button></div>`;else if(stage==='daring-otp-boundary')body='<h3>Validasi awal diterima</h3><p>Respons layanan mengizinkan proses menuju OTP. Akun belum dinyatakan terverifikasi.</p><p>Lanjutkan OTP dan verifikasi wajah melalui aplikasi Android Sentuh Tanahku. Tahap tersebut belum tersedia di webapp.</p><div class="modal-actions"><button type="button" class="button secondary" data-action="verification-dismiss">Tutup</button></div>';else body=`<h3>Periksa data identitas</h3><p>Lima kolom berikut akan dikirim ke layanan Sentuh Tanahku (ATR/BPN) untuk validasi awal identitas.</p><dl class="verification-daring-review">${DARING_FIELDS.map(field=>`<div><dt>${esc(field.label)}</dt><dd>${esc(model.snapshot[field.key])}</dd></div>`).join('')}</dl>${model.problem?`<p class="notice error" role="alert">${esc(model.problem)}</p>`:''}<div class="modal-actions"><button type="button" class="button secondary" data-action="verification-daring-back" ${stage==='daring-sending'?'disabled':''}>Ubah data</button><button type="button" class="button" data-action="verification-daring-send" ${stage==='daring-sending'?'disabled':''}>${stage==='daring-sending'?'Mengirim…':'Kirim untuk validasi'}</button></div>`;modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${DARING_COPY.title}</h2></div><section class="modal-body verification-dialog verification-daring" data-verification-dialog ${stage==='daring-sending'?'aria-busy="true"':''}>${body}</section>`;owner.element=modal.querySelector('[data-verification-dialog]');if(stage!=='daring-sending')modal.querySelector(stage==='daring-form'?'input':stage==='daring-info'?'[data-action="verification-daring-ok"]':stage==='daring-review'?'[data-action="verification-daring-back"]':'[data-action="verification-dismiss"]')?.focus({preventScroll:true});}
function verificationDaringInput(input){const owner=flowResults.get('verification:dialog-state');if(!verificationDialogCurrent(owner,input)||owner.stage!=='daring-form'||!DARING_FIELDS.some(field=>field.key===input.dataset.daringField))return;const key=input.dataset.daringField,model=owner.daring;try{model.values[key]=key==='TglLahir'?daringDateFromInput(input.value):input.value;model.errors[key]=daringEditError(key,model.values[key]);}catch{model.values[key]='';model.errors[key]='Tanggal lahir belum sesuai rentang kalender.';}model.problem='';model.snapshot=null;input.setAttribute('aria-invalid',String(!!model.errors[key]));const error=owner.element.querySelector('#verification-daring-'+key+'-error');if(error)error.textContent=model.errors[key]??'';}
function verificationDaringContinue(form){const owner=flowResults.get('verification:dialog-state');if(!verificationDialogCurrent(owner,form)||owner.stage!=='daring-form'||form.id!=='verification-daring-form'||!verificationDaringOperation())return;for(const field of DARING_FIELDS){const input=form.elements.namedItem(field.key);if(!input)return;verificationDaringInput(input);}const model=owner.daring,validation=daringFinalValidation(model.values);model.errors=validation.errors;model.problem='';if(!validation.valid){model.info=DARING_COPY.incomplete;owner.stage='daring-info';}else{model.snapshot=daringSnapshot(model.values);owner.stage='daring-review';}verificationDaringPaint(owner);}
function verificationDaringBack(button){const owner=flowResults.get('verification:dialog-state');if(!verificationDialogCurrent(owner,button)||!owner.daring)return;if(owner.stage==='daring-form'){owner.stage='methods';owner.method=0;verificationMethodsPaint(owner);}else if(owner.stage==='daring-review'){owner.stage='daring-form';owner.daring.snapshot=null;verificationDaringPaint(owner);}}
function verificationDaringInfoClose(button){const owner=flowResults.get('verification:dialog-state');if(!verificationDialogCurrent(owner,button)||owner.stage!=='daring-info')return;owner.stage='daring-form';owner.daring.snapshot=null;verificationDaringPaint(owner);}
function verificationDaringResponse(response){const body=response?.data;if(!Number.isInteger(response?.status)||response.status<200||response.status>=300||!body||typeof body!=='object'||Array.isArray(body)||typeof body.error!=='boolean'||typeof body.message!=='string')return null;return {error:body.error,message:body.message};}
