function humanField(key){return ({nomor:'Nomor',nomorberkas:'Nomor berkas',nomorBerkas:'Nomor berkas',nomorsertifikat:'Nomor sertipikat',nomorSertipikat:'Nomor sertipikat',jenisHak:'Jenis hak',nama:'Nama',title:'Judul',judul:'Judul',status:'Status',tanggal:'Tanggal',kantor:'Kantor pertanahan',luas:'Luas',alamat:'Alamat',provinsi:'Provinsi',kabupaten:'Kabupaten/kota',kecamatan:'Kecamatan',kelurahan:'Kelurahan/desa'})[key]||key.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/_/g,' ');}
