function nativeInformationBody(response){if(response?.status!==200)return null;let body=response.data;if(typeof body==='string'){try{body=JSON.parse(body);}catch{return null;}}return body&&typeof body==='object'&&!Array.isArray(body)&&body.error!==true?body:null;}
function isInformationItem(item){return !!item&&typeof item==='object'&&!Array.isArray(item)&&['layananId','nama','deskripsi','grup'].every(key=>item[key]==null||typeof item[key]==='string')&&(item.tipeSimulasi==null||Number.isInteger(item.tipeSimulasi));}
function informationRows(response){const rows=nativeInformationBody(response)?.data;return Array.isArray(rows)&&rows.every(isInformationItem)?rows:null;}
function informationDetail(response){const detail=nativeInformationBody(response)?.data;return detail&&typeof detail==='object'&&!Array.isArray(detail)&&['layananId','nama','tarif'].every(key=>detail[key]==null||typeof detail[key]==='string')&&['persayaratan','penyelesaian','keterangan'].every(key=>detail[key]==null||Array.isArray(detail[key])&&detail[key].every(item=>typeof item==='string'))&&(detail.tipeSimulasi==null||Number.isInteger(detail.tipeSimulasi))?detail:null;}
function getInformationState(){let owner=flowResults.get('information:default');if(!owner?.information){owner={information:true,attempted:false,scheduled:false,loading:false,rows:null,error:'',query:'',listRequest:null,detail:null};flowResults.set('information:default',owner);}return owner;}
function informationGroups(rows,query=''){const groups=new Map(),needle=query.toLowerCase();rows.forEach((item,index)=>{if(needle&&!['nama','deskripsi','grup'].some(key=>typeof item[key]==='string'&&item[key].toLowerCase().includes(needle)))return;const label=item.grup??'Lainnya';if(!groups.has(label))groups.set(label,[]);groups.get(label).push({item,index});});return [...groups].map(([label,items])=>({label,items}));}
function informationListView(owner){const groups=informationGroups(owner.rows||[],owner.query);if(!groups.length)return `<section class="panel flow-empty">${empty(owner.rows?.length?'Layanan tidak ditemukan.':'Tidak ada data informasi layanan.','','folder')}</section>`;return `<div class="information-groups">${groups.map(group=>`<section class="information-group"><h2>${esc(group.label)}</h2><div class="information-list">${group.items.map(({item,index})=>`<button class="information-item" data-action="flow-detail" data-index="${index}" ${typeof item.layananId==='string'&&item.layananId.trim()?'':'disabled'}><span><strong>${esc(item.nama??'-')}</strong><span>${esc(item.deskripsi??'-')}</span></span>${icon('chevron',20)}</button>`).join('')}</div></section>`).join('')}</div>`;}
function informationSection(title,items){return items?.length?`<section class="service-detail-section"><h3>${title}</h3><ol>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ol></section>`:'';}
function informationDetailView(owner){const frame=owner.detail,details=frame?.response&&informationDetail(frame.response);const back=`<div class="information-back"><button class="button secondary small" data-action="information-back">${icon('arrow',16)} Kembali ke daftar layanan</button></div>`;if(frame?.loading)return `${head('INFO LAYANAN',esc(frame.item.nama??'Detail layanan'),'')}${back}<section class="panel flow-empty">${empty('Memuat detail layanan…','Mengambil informasi dari layanan.','clock')}</section>`;if(!details)return `${head('INFO LAYANAN',esc(frame?.item.nama??'Detail layanan'),'')}${back}${notice(`Gagal memuat detail layanan.${frame?.error?' '+esc(frame.error):''}`,'error')}<button class="button secondary" data-action="information-detail-retry">Coba lagi</button>`;return `${head('INFO LAYANAN',esc(details.nama??''),'')}${back}<section class="panel information-detail">${frame.item.deskripsi?`<p class="information-description">${esc(frame.item.deskripsi)}</p>`:''}${informationSection('Persyaratan',details.persayaratan)}${informationSection('Waktu Penyelesaian',details.penyelesaian)}${informationSection('Keterangan Tambahan',details.keterangan)}${details.tarif!=null?`<section class="service-detail-section"><h3>Tarif</h3><p>${esc(details.tarif)}</p></section>`:''}${informationSimulationView(owner,frame,details)}</section>`;}
function informationPage(){const owner=getInformationState(),op=state.operations.find(op=>op.endpoint==='InfoLayanan/GetInfoLayanan'&&ready(op)&&!write(op)),available=!!op&&state.connection.configured&&!state.loading;if(available&&!owner.attempted&&!owner.scheduled){owner.scheduled=true;queueMicrotask(()=>{owner.scheduled=false;if(route==='information'&&flowResults.get('information:default')===owner&&!owner.attempted)loadInformationList();});}if(owner.detail)return informationDetailView(owner);return `${head('SENTUH TANAHKU','Info Layanan','Temukan informasi dan persyaratan pengurusan pertanahan.')}<section class="panel information-controls"><label class="native-list-search">Cari layanan<input id="flow-search" type="search" placeholder="Cari layanan" value="${esc(owner.query)}" autocomplete="off"></label><button class="button secondary" data-action="information-load" ${!available||owner.loading?'disabled':''}>${icon('refresh',16)} ${owner.loading?'Memuat…':owner.error?'Coba lagi':'Perbarui'}</button></section>${!state.connection.configured?notice(esc(state.connection.reason||'Koneksi belum dikonfigurasi.')):!op&&!state.loading?notice('Informasi layanan belum tersedia pada build ini.') :''}${owner.loading||!owner.attempted?`<section class="panel flow-empty">${empty('Memuat informasi layanan…','Tunggu respons layanan.','clock')}</section>`:owner.error?notice(`Gagal memuat data. Silakan coba lagi. ${esc(owner.error)}`,'error'):informationListView(owner)}`;}
async function loadInformationList(){if(route!=='information'||!state.connection.configured||state.loading)return;const owner=getInformationState(),op=state.operations.find(op=>op.endpoint==='InfoLayanan/GetInfoLayanan'&&ready(op)&&!write(op));if(!op||owner.loading)return;const epoch=sessionEpoch,request={};owner.attempted=true;owner.loading=true;owner.error='';owner.rows=null;owner.detail=null;owner.listRequest=request;const current=()=>route==='information'&&flowResults.get('information:default')===owner&&owner.listRequest===request&&epoch===sessionEpoch;render();try{const response=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{}}});if(!current())return;const rows=informationRows(response.result);if(!rows)throw new Error('Respons informasi layanan belum dikenali.');owner.rows=rows;state.results.set(op.id,response.result);record('Info Layanan','success',`HTTP ${response.result.status} · Respons diterima`);}catch(error){if(!current())return;owner.error=error.message;state.results.delete(op.id);record('Info Layanan','error',`${error.code||'ERROR'} · ${error.message}`);if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);}}finally{if(current()){owner.loading=false;owner.listRequest=null;render();}}}
function openInformationDetail(index){if(route!=='information'||!Number.isInteger(index)||index<0)return;const owner=getInformationState(),item=owner.rows?.[index];if(!isInformationItem(item)||typeof item.layananId!=='string'||!item.layananId.trim())return;return loadServiceDetail(item);}
async function loadServiceDetail(item){if(route!=='information'||!state.connection.configured)return;const owner=getInformationState();if(!owner.rows?.includes(item)||!isInformationItem(item)||typeof item.layananId!=='string'||!item.layananId.trim())return;const op=state.operations.find(op=>op.endpoint==='InfoLayanan/GetInfoLayananDetail?id={value}'&&ready(op)&&!write(op));if(!op)return;if(owner.detail?.item===item&&owner.detail.loading)return;const epoch=sessionEpoch,request={},frame={item,response:null,loading:true,error:'',request};owner.detail=frame;const current=()=>route==='information'&&flowResults.get('information:default')===owner&&owner.detail===frame&&frame.request===request&&epoch===sessionEpoch;render();window.scrollTo(0,0);try{const response=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{id:item.layananId}}});if(!current())return;if(!informationDetail(response.result))throw new Error('Respons detail layanan belum dikenali.');frame.response=response.result;record('Detail Info Layanan','success',`HTTP ${response.result.status} · Respons diterima`);}catch(error){if(!current())return;frame.error=error.message;record('Detail Info Layanan','error',`${error.code||'ERROR'} · ${error.message}`);if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);}}finally{if(current()){frame.loading=false;frame.request=null;render();}}}
function backInformation(){if(route!=='information')return;const owner=getInformationState();owner.detail=null;render();window.scrollTo(0,0);}
function filterInformation(input){if(route!=='information'||!input.isConnected)return;const owner=getInformationState();if(owner.detail)return;const start=input.selectionStart,end=input.selectionEnd;owner.query=input.value;render();const replacement=$('#flow-search');if(replacement){replacement.focus({preventScroll:true});if(start!==null&&end!==null)replacement.setSelectionRange(start,end);}}
function nativeAccountSummary(response){const body=nativeResponseObject(response),profile=body?.data;return response?.status===200&&body?.error===false&&profile&&typeof profile==='object'&&!Array.isArray(profile)?profile:null;}
function visibleNativeMenus(){const op=state.operations.find(o=>o.endpoint==='account/account_summary');const profile=state.authenticated&&op?nativeAccountSummary(state.results.get(op.id)):null;const eligible=profile&&profile.roleUser==='PERORANGAN'&&Number.isInteger(profile.statusVerifikasi)&&profile.statusVerifikasi!==-1&&![true,'true','1'].includes(profile.isIkd);return eligible?primaryMenus:primaryMenus.filter(([key])=>!['collections','activity'].includes(key));}
async function refreshNativeProfile(accept=()=>true){const op=state.operations.find(o=>o.endpoint==='account/account_summary'&&ready(o)&&!write(o));if(!state.authenticated||logoutPending||!op||!accept())return;const epoch=sessionEpoch,key='accountsummary:default',request={loading:true,profileAuto:true},current=()=>epoch===sessionEpoch&&flowResults.get(key)===request&&accept();flowResults.set(key,request);try{const data=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{}}});if(!current())return;if(!nativeAccountSummary(data.result))throw new Error('Respons profil belum dikenali. Coba muat profil kembali.');state.results.set(op.id,data.result);Object.assign(request,{response:data.result,loading:false});state.profileError='';record('Profil akun','success',`HTTP ${data.result.status} · Respons diterima`);}catch(e){if(!current())return;Object.assign(request,{error:e.message,loading:false});state.results.delete(op.id);state.profileError=e.message;record('Profil akun','error',`${e.code||'ERROR'} · ${e.message}`);if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(e.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(e.message);}}}
function account(){return `${head('SENTUH TANAHKU','Profil','Kelola akun dan akses informasi aplikasi.')}<div class="profile-layout"><div>${loginCard()}${state.authenticated?`<section class="panel profile-account-actions"><h2>Informasi akun</h2><a href="#/accountsummary">Data akun ${icon('chevron',16)}</a><a href="#/verification">Status verifikasi ${icon('chevron',16)}</a>${visibleNativeMenus().filter(([key])=>['collections','activity'].includes(key)).map(([key,label])=>`<a href="#/${key}">${esc(label)} ${icon('chevron',16)}</a>`).join('')}</section>`:''}</div><div><section class="panel profile-menu"><h2>Pengaturan & informasi</h2>${profileMenus.map(m=>`<a href="#/${m.route}"><span>${m.asset?`<img src="assets/icons/${m.asset}" alt="">`:icon(m.icon,21)}</span><strong>${m.label}</strong>${icon('chevron',16)}</a>`).join('')}${state.authenticated?`<button data-action="logout"><span>${icon('user',21)}</span><strong>Keluar</strong>${icon('chevron',16)}</button>`:''}</section>${state.profileError?notice(`Informasi profil belum dapat dimuat: ${esc(state.profileError)} <a class="text-link" href="#/accountsummary">Coba muat profil</a>`,'error'):''}<details class="profile-connection panel"><summary>Koneksi browser</summary><dl class="detail-list"><div><dt>Tujuan layanan</dt><dd>${esc(state.connection.origin||'Belum tersedia')}</dd></div><div><dt>Versi sumber</dt><dd>${esc(state.version)}</dd></div></dl>${state.connection.reason?notice(esc(state.connection.reason)):''}<a class="text-link" href="#/testing">Buka pengujian lanjutan ${icon('arrow',14)}</a></details></div></div>`;}
