function htField(row,primary,fallback){return row?.[primary]??row?.[fallback]??null;}
function htDetailTarget(item){const id=htField(item,'HaktanggunganId','haktanggunganId');return typeof id==='string'&&id.trim()?{endpoint:'legacy/GetSertipikatHTDetail',values:{haktanggunganId:id}}:null;}
function isHtDetail(data){const fields=[['HaktanggunganId','haktanggunganId'],['Nama','nama'],['NomorHak','nomorHak'],['Nibel','nibel'],['JenisHak','jenisHak']];return Array.isArray(data)&&data.every(row=>row&&typeof row==='object'&&!Array.isArray(row)&&(Object.keys(row).length===0||fields.some(pair=>pair.some(key=>Object.hasOwn(row,key))))&&fields.every(([a,b])=>htField(row,a,b)===null||typeof htField(row,a,b)==='string'));}
function htDetailRows(data,query=''){const search=String(query).toLowerCase(),rows=data.filter(row=>!search||[['Nama','nama'],['JenisHak','jenisHak'],['NomorHak','nomorHak']].some(([a,b])=>(htField(row,a,b)??'').toLowerCase().includes(search)));return rows.map(row=>{const nomor=htField(row,'NomorHak','nomorHak'),nibel=htField(row,'Nibel','nibel');return `<article class="ht-certificate" role="listitem"><div><h3>${certificateText(htField(row,'Nama','nama'))}</h3><p class="ht-number">${certificateText(nomor??nibel)}</p><p class="ht-right">${certificateText(htField(row,'JenisHak','jenisHak'))}</p></div><span class="ht-badge" aria-label="Sertipikat ${nomor!==null?'analog':'elektronik'}">${nomor!==null?'A':'E'}</span></article>`;}).join('');}
function htDetailView(response){const data=flowData(response);if(!isHtDetail(data))return result(response);return `<div class="certificate-detail ht-detail"><label class="ht-search">Cari nomor hak<input id="ht-search" type="search" placeholder="Cari nomor hak" autocomplete="off"></label><div class="ht-results" role="list" aria-label="Daftar sertipikat hak tanggungan" aria-live="polite">${htDetailRows(data)}</div></div>`;}
