function scanLocationPaint(owner,frame){if(!scanLocationCurrent(owner,frame))return;const snapshot=frame.controller.snapshot();if(!snapshot)return;const tabs=frame.slot.querySelector('[data-scan-location-tabs]'),panes=frame.slot.querySelector('[data-scan-location-panes]');tabs.hidden=snapshot.branches.length<2;for(const branch of snapshot.branches){let button=tabs.querySelector(`[data-scan-location-kind="${branch.kind}"]`),pane=panes.querySelector(`[data-scan-location-pane="${branch.kind}"]`);if(!button){button=document.createElement('button');button.setAttribute('type','button');button.setAttribute('role','tab');button.setAttribute('data-action','scan-location-tab');button.setAttribute('data-scan-location-kind',branch.kind);button.setAttribute('aria-controls',`scan-location-${frame.sequence}-${branch.kind}`);button.textContent=branch.title;tabs.appendChild(button);}if(!pane){pane=document.createElement('section');pane.className='scan-location-pane';pane.id=`scan-location-${frame.sequence}-${branch.kind}`;pane.setAttribute('role','tabpanel');pane.setAttribute('data-scan-location-pane',branch.kind);panes.appendChild(pane);}button.setAttribute('aria-selected',String(branch.kind===snapshot.active));pane.hidden=branch.kind!==snapshot.active;const previous=frame.painted.get(branch.kind);if(previous&&previous.stage===branch.stage&&previous.response===branch.response&&previous.error===branch.error)continue;frame.painted.set(branch.kind,{stage:branch.stage,response:branch.response,error:branch.error});if(branch.stage==='ready'){if(branch.kind==='pbt')scanLocationPbtView(owner,frame,pane,branch.response);else if(branch.kind==='kkpr')scanLocationKkprView(owner,frame,pane,branch.response);else pane.innerHTML=activityDocumentGeoView(branch.response);}else pane.innerHTML=branch.stage==='error'?notice(esc(branch.error||'Lokasi dokumen belum dapat dimuat.'),'error'):'<p class="berkas-empty" role="status">Memuat lokasi dokumen…</p>';}}
