function activityDocumentGeoData(response){if(response?.status!==200)throw new Error('Lokasi dokumen belum dapat dibaca. Coba muat kembali.');let body=response.data;if(typeof body==='string'){try{body=JSON.parse(body);}catch{throw new Error('Format lokasi dokumen belum dikenali.');}}if(body!=null&&(typeof body!=='object'||Array.isArray(body)))throw new Error('Format lokasi dokumen belum dikenali.');if(body?.geometri==null)return {type:'FeatureCollection',features:[]};const geometry=body.geometri,coordinates=geometry?.coordinates;if(typeof geometry!=='object'||Array.isArray(geometry)||typeof geometry.type!=='string'||!Array.isArray(coordinates)||!coordinates.every(polygon=>Array.isArray(polygon)&&polygon.every(ring=>Array.isArray(ring)&&ring.every(vertex=>Array.isArray(vertex)&&vertex.every(ordinate=>typeof ordinate==='number'&&Number.isFinite(ordinate))))))throw new Error('Struktur geometri lokasi dokumen belum sesuai.');if(body.tipeHak!=null&&typeof body.tipeHak!=='string')throw new Error('Jenis hak lokasi dokumen belum sesuai.');return {type:'FeatureCollection',features:[{type:'Feature',geometry:{type:'MultiPolygon',coordinates},properties:{tipehak:body.tipeHak??'Belum Terdaftar'}}]};}
function activityDocumentGeoView(response){let view;try{view=parcelMapView(activityDocumentGeoData(response)).replace('<h3>Batas Bidang Tanah</h3>','').replace('aria-label="Batas bidang dari layanan"','aria-label="Lokasi bidang dari dokumen"');}catch(error){view=notice(esc(error.message),'error');}return `<section class="kkpr-section" aria-label="Lokasi Bidang"><h3>Lokasi Bidang</h3>${view}<details class="json-details"><summary>Data lokasi dari layanan</summary><pre>${json(response?.data)}</pre></details></section>`;}
async function loadActivityDocumentGeo(button){const slot=button.closest('.activity-document-geo')?.querySelector('.activity-document-geo-result'),dialog=button.closest('dialog'),q=button.dataset.documentId,epoch=sessionEpoch,sequence=detailSequence;if(!slot||!slot.isConnected||!dialog?.open||button.dataset.loading==='true'||!state.authenticated||typeof q!=='string'||!q.trim())return;const op=state.operations.find(o=>o.endpoint==='/apis/getGeoJsonInfo'&&ready(o)&&!write(o));if(!op){slot.innerHTML=notice('Pembacaan lokasi dokumen belum tersedia pada build server ini.');return;}const current=()=>epoch===sessionEpoch&&sequence===detailSequence&&slot.isConnected&&dialog.open;button.dataset.loading='true';button.disabled=true;button.textContent='Memuat lokasi…';slot.innerHTML='<p class="berkas-empty">Mengambil lokasi dokumen dari layanan…</p>';try{const response=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{q}}});if(!current())return;slot.innerHTML=activityDocumentGeoView(response.result);record('Lokasi dokumen','success',`HTTP ${response.result.status} · Respons diterima`);}catch(error){if(epoch!==sessionEpoch)return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);return;}if(!current())return;slot.innerHTML=notice(esc(error.message),'error');record('Lokasi dokumen','error',`${error.code||'ERROR'} · ${error.message}`);}finally{if(current()&&button.isConnected){button.dataset.loading='false';button.disabled=false;button.textContent='Muat kembali lokasi';}}}
