function nativeListResultView(context,response){const mode=nativeListMode(context);if(mode==='collection')return collectionListView(context,response);if(mode==='activity')return activityListView(response);if(mode==='kkpr')return kkprListView(response);if(!mode)return null;const rows=mode==='akta'?aktaRows(response):dataItems(flowData(response));if(!Array.isArray(rows)||!rows.every(row=>mode==='akta'?isAktaItem(row):certificateListItem(row)))return null;const query=flowQuery,items=rows.map((item,index)=>({item,index})).filter(({item})=>mode==='akta'?aktaMatches(item,query):certificateListMatches(item,query)),start=flowPageIndex*20,label=mode==='akta'?'Cari akta':'Cari nomor atau nama';const search=`<label class="native-list-search">${label}<input id="flow-search" type="search" placeholder="${label}" value="${esc(query)}" autocomplete="off"></label>`;if(!items.length)return `${search}<section class="panel flow-empty">${empty(mode==='akta'?'Kamu belum memiliki Akta':'Belum ada sertipikat yang ditampilkan','','folder')}<button class="button secondary small" data-action="flow-load">Coba Lagi</button></section>`;return `${search}<div class="server-data-heading"><span>${start+1}–${Math.min(start+20,items.length)} dari ${items.length} item ditampilkan</span>${badge('Respons server','success')}</div><div class="${mode==='akta'?'akta-card-grid':'data-card-grid'}">${items.slice(start,start+20).map(({item,index})=>mode==='akta'?aktaCard(item,index):certificateListCard(item,index)).join('')}</div>${items.length>20?`<div class="flow-pagination"><button class="button secondary small" data-action="flow-page" data-index="${flowPageIndex-1}" ${flowPageIndex===0?'disabled':''}>Sebelumnya</button><span>Halaman ${flowPageIndex+1} dari ${Math.ceil(items.length/20)}</span><button class="button secondary small" data-action="flow-page" data-index="${flowPageIndex+1}" ${start+20>=items.length?'disabled':''}>Berikutnya</button></div>`:''}`;}
