// Mitra list models and parent selection follow the bounded APK evidence in MITRA-FLOW.md.
function resetPartnerNavigation(){if(partnerFrame&&flowResults.get(partnerFrame.key)?.loading)flowResults.delete(partnerFrame.key);partnerFrame=null;}
function partnerFlowContext(def){if(!partnerFrame){const tab=def.tabs.find(t=>t.id===flowTab&&!t.parent)||def.tabs.find(t=>!t.parent);partnerFrame={tabId:tab.id,key:`partners:${tab.id}`,values:{},parent:null,title:null,kind:'0',query:'',page:0};}const original=def.tabs.find(t=>t.id===partnerFrame.tabId);if(!original)return null;const tab={...original,values:partnerFrame.values,form:false};return {def,tab,key:partnerFrame.key,partnerFrame,op:state.operations.find(o=>o.endpoint===tab.endpoint&&ready(o))||state.operations.find(o=>o.endpoint===tab.endpoint)};}
function partnerItem(mode,item){if(!item||typeof item!=='object'||Array.isArray(item))return null;const fields={kantorppat:['kantorId','nama'],wilayah:['wilayahId','nama'],penilai:['nama'],ppat:['nama','alamatKantor','tmtPensiun','totalAkta','isPPAT','nomorSK'],surveyor:['nama','jenisSurveyor','nomorLisensi']}[mode];if(!fields)return null;const ignored={kantorppat:['kode'],ppat:['tempatKedudukan','status']}[mode]||[];if([...fields,...ignored].some(key=>item[key]!=null&&typeof item[key]!=='string'))return null;return Object.fromEntries(fields.map(key=>[key,item[key]??null]));}
function partnerRows(mode,response){const body=nativeResponseObject(response);if(response?.status!==200||!Array.isArray(body?.data))return null;const rows=body.data.map(item=>partnerItem(mode,item));return rows.every(Boolean)?rows:null;}
function partnerChildTarget(mode,item){const row=partnerItem(mode,item);if(!row)return null;if(mode==='kantorppat')return {tabId:'ppat',endpoint:'Mitra/GetPPATList?kantorId={value}',values:{kantorId:row.kantorId??''},title:`Daftar PPAT ${(row.nama??'No Address').replaceAll('Kantor Pertanahan ','')}`};if(mode==='wilayah')return {tabId:'surveyor',endpoint:'Mitra/GetSurveyorList?wilayahId={value}',values:{wilayahId:row.wilayahId??''},title:`Daftar Surveyor Provinsi ${row.nama??''}`};return null;}
function partnerItemMatches(mode,item,query,kind='0'){const row=partnerItem(mode,item);if(!row)return false;if(mode==='ppat'&&row.isPPAT!==(kind==='0'?'1':'0'))return false;if(mode==='surveyor'&&row.jenisSurveyor!==(kind==='0'?'Surveyor Kadaster':'Asisten Surveyor Kadaster'))return false;const needle=query.toLowerCase();return (row.nama??'').toLowerCase().includes(needle)||(mode==='ppat'&&(row.alamatKantor??'').toLowerCase().includes(needle));}
function partnerAktaBucket(value){let count=0n;if(typeof value==='string'){const text=value.replace(/^[\s\u0085]+|[\s\u0085]+$/g,''),negative=text.startsWith('-'),digits=text.replace(/^[+-]/,'');try{if(/^0[xX][0-9a-fA-F]+$/.test(digits)){const magnitude=BigInt(digits);if(negative&&magnitude<=9223372036854775808n)count=-magnitude;else if(!negative&&magnitude<=18446744073709551615n)count=BigInt.asIntN(64,magnitude);}else if(/^\d+$/.test(digits)){count=BigInt(text);if(count>9223372036854775807n||count< -9223372036854775808n)count=0n;}}catch{}}return count<=0n?'0':count<=10n?'<10':count<=30n?'10-30':count<=50n?'30-50':count<=100n?'50-100':'>100';}
