// Cari Berkas: native office selection, local challenge and ordered reads.
function generateSearchFileCaptcha(){let value='';while(value.length<6){const bytes=crypto.getRandomValues(new Uint8Array(12));for(const byte of bytes){if(byte<250)value+=String(byte%10);if(value.length===6)break;}}return value;}
function searchFileYears(){const year=new Date().getFullYear();return [String(year-1),String(year)];}
function getSearchFileState(){if(!searchFileState)searchFileState={offices:null,officeStatus:'idle',officeError:'',officeQuery:'',officePage:0,selectedOffice:null,nomor:'',tahun:searchFileYears()[1],captcha:generateSearchFileCaptcha(),captchaInput:'',errors:{},busy:false,message:'',response:null,sop:null,print:'-',request:null,officeRequest:null};return searchFileState;}
function resetSearchFileNavigation(){searchFileState=null;flowResults.delete('searchfile:default');}
function searchFileOperation(endpoint){return state.operations.find(op=>op.endpoint===endpoint&&ready(op)&&!write(op))||null;}
function searchFileTyped(row,spec){if(!row||typeof row!=='object'||Array.isArray(row))return null;const value={};for(const [key,type] of Object.entries(spec)){const field=row[key]??null;if(field!==null&&!(type==='s'?typeof field==='string':type==='i'?Number.isInteger(field):type==='b'?typeof field==='boolean':typeof field==='number'&&Number.isFinite(field)))return null;value[key]=field;}return value;}
function searchFileOfficeRows(response){if(response?.status!==200||!Array.isArray(response.data))return null;const rows=response.data.map(row=>searchFileTyped(row,{Alamat:'s',Email:'s',Fax:'s',KantorId:'s',Nama:'s',Telp:'s',Kota:'s',TipeKantorId:'i'}));return rows.every(Boolean)?rows:null;}
function searchFileOfficeMatches(row,query){return (row.Nama??'').toLowerCase().includes(query.toLowerCase().trim());}
function searchFileOfficeEntries(owner){const profile=nativeAccountSummary(flowResults.get('accountsummary:default')?.response),preferred=typeof profile?.kantorId==='string'?profile.kantorId:null,entries=(owner.offices||[]).map((item,index)=>({item,index,preferred:preferred!==null&&item.KantorId===preferred})),first=entries.findIndex(row=>row.preferred);if(first>0)entries.unshift(entries.splice(first,1)[0]);return entries;}
