document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;if(action==='queue-preread-start'){await queuePrereadStart(button);return;}if(!['queue-preread-close','queue-preread-offices','queue-preread-locations','queue-preread-next','queue-preread-back','queue-preread-refresh','queue-preread-calendar','queue-preread-review','queue-preread-review-close','queue-booking-cancel','queue-booking-confirm','queue-booking-reconcile'].includes(action))return;const owner=flowResults.get('queue:preread');if(!queuePrereadCurrent(owner,button)||button.disabled)return;if(action==='queue-preread-review'){if(!/^(?:0|[1-9][0-9]*)$/.test(button.dataset.index??'')||!/^(?:0|[1-9][0-9]*)$/.test(button.dataset.generation??''))return;if(owner.booking)await owner.booking.begin(Number(button.dataset.index),Number(button.dataset.generation));else owner.controller.reviewLoket(Number(button.dataset.index),Number(button.dataset.generation));}else if(action==='queue-booking-cancel')owner.booking?.cancel();else if(action==='queue-booking-confirm')await owner.booking?.confirm();else if(action==='queue-booking-reconcile')await owner.booking?.reconcile();else if(action==='queue-preread-review-close')owner.controller.closeReview();else if(action==='queue-preread-close')queuePrereadClose(button);else if(action==='queue-preread-offices')await owner.controller.reloadOffices();else if(action==='queue-preread-locations'){const index=owner.controller.state.offices?.indexOf(owner.controller.state.office);await owner.controller.selectOffice(index);}else if(action==='queue-preread-next')await owner.controller.next();else if(action==='queue-preread-back'){owner.dateDraft=null;owner.controller.back();}else if(action==='queue-preread-refresh')await owner.controller.refresh();else if(action==='queue-preread-calendar')await owner.controller.loadCalendar(owner.controller.state.date.getFullYear());});
document.addEventListener('change',async event=>{if(!['queue-preread-office','queue-preread-location','queue-preread-count'].includes(event.target.id))return;const owner=flowResults.get('queue:preread');if(!queuePrereadCurrent(owner,event.target)||event.target.disabled||event.target.value===''||!/^\d+$/.test(event.target.value))return;const index=Number(event.target.value);if(event.target.id==='queue-preread-count'){if(/^[1-5]$/.test(event.target.value))owner.controller.setDocumentCount(index);return;}if(event.target.id==='queue-preread-office')await owner.controller.selectOffice(index);else owner.controller.selectLocation(index);});
