function queueCallTime(item){if(!queueStrings(item,['pesan','pengirim','penerima','tanggal_dikirim']))return null;let micros,date;if(item.timeKind==='instant'){if(typeof item.epochMicroseconds!=='string'||!/^-?(?:0|[1-9][0-9]{0,18})$/.test(item.epochMicroseconds)||item.localDateTime!=null)return null;micros=BigInt(item.epochMicroseconds);if(micros< -8640000000000000000n||micros>8640000000000000000n)return null;date=new Date(Number(micros/1000n-(micros<0n&&micros%1000n!==0n?1n:0n)));}else if(item.timeKind==='local'){const p=item.localDateTime;if(item.epochMicroseconds!==null||!queueObject(p)||!['year','month','day','hour','minute','second','microsecond'].every(key=>Number.isInteger(p[key]))||p.year< -271821||p.year>275760||p.month<1||p.month>12||p.day<1||p.day>31||p.hour<0||p.hour>23||p.minute<0||p.minute>59||p.second<0||p.second>59||p.microsecond<0||p.microsecond>999999)return null;const calendar=new Date(0);calendar.setUTCFullYear(p.year,p.month-1,p.day);if(calendar.getUTCFullYear()!==p.year||calendar.getUTCMonth()!==p.month-1||calendar.getUTCDate()!==p.day)return null;date=new Date(0);date.setFullYear(p.year,p.month-1,p.day);date.setHours(p.hour,p.minute,p.second,Math.floor(p.microsecond/1000));if(!Number.isFinite(date.getTime()))return null;micros=BigInt(date.getTime())*1000n+BigInt(p.microsecond%1000);if(micros< -8640000000000000000n||micros>8640000000000000000n)return null;}else return null;if(!Number.isFinite(date.getTime()))return null;const parts=new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date),time=parts.find(part=>part.type==='hour').value+':'+parts.find(part=>part.type==='minute').value;return {micros,date,time};}
function queueCallsRows(response){const body=response?.data;return Number.isInteger(response?.status)&&response.status>=200&&response.status<300&&queueObject(body)&&Array.isArray(body.data)&&body.data.every(item=>queueCallTime(item))?body.data:null;}
function queueCallsListView(calls){if(!calls.rows?.length)return `<section class="panel flow-empty queue-empty">${empty('Belum ada panggilan, nih!','Halaman ini buat nunjukin panggilan Antrian Daring. Kamu bakal dapet info kalau antrianmu udah dekat.','clock')}</section>`;const rows=calls.rows.map((item,index)=>({item,index,...queueCallTime(item)})).sort((a,b)=>a.micros===b.micros?a.index-b.index:a.micros>b.micros?-1:1);return `<div class="queue-calls-list">${rows.map(({item,time})=>`<article class="queue-call-card"><div class="queue-call-heading"><h2>${esc('Panggilan '+item.pengirim)}</h2><span class="queue-call-time">${esc(time)}</span></div><p class="queue-call-recipient">${esc(item.penerima)}</p><p class="queue-call-message">${esc(item.pesan)}</p></article>`).join('')}</div>`;}
