async function loadQueueCalls(refresh=false){if(route!=='queue'||flowTab!=='panggilan'||!state.authenticated||!state.connection.configured||state.loading)return;const owner=getQueueState(),calls=owner.calls,op=queueOperation('api/notifikasi');if(!op||calls.loading||calls.attempted&&!refresh)return;const epoch=sessionEpoch,navigation=detailSequence,request={};Object.assign(calls,{attempted:true,scheduled:false,loading:true,error:'',request});state.results.delete(op.id);const current=()=>route==='queue'&&flowTab==='panggilan'&&state.authenticated&&epoch===sessionEpoch&&navigation===detailSequence&&flowResults.get('queue:default')===owner&&owner.calls===calls&&calls.request===request;render();try{const response=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{}}});if(!current())return;const rows=queueCallsRows(response.result);if(!rows)throw new Error('Respons panggilan belum sesuai format layanan. Coba perbarui.');calls.rows=rows;state.results.set(op.id,response.result);record('Panggilan Antrian','success',`HTTP ${response.result.status} · ${rows.length} panggilan diterima`);}catch(error){if(!current())return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);return;}calls.error=error.message;record('Panggilan Antrian','error',`${error.code||'ERROR'} · ${error.message}`);}finally{if(current()){calls.loading=false;calls.request=null;render();}}}
