async function loadQueueList(refresh=false){if(route!=='queue'||flowTab==='panggilan'||!state.authenticated||!state.connection.configured||state.loading)return;const owner=getQueueState(),op=queueOperation('api/antrian/saya');if(!op||owner.loading||owner.attempted&&!refresh)return;const epoch=sessionEpoch,navigation=detailSequence,request={};Object.assign(owner,{attempted:true,scheduled:false,loading:true,error:'',rows:null,detail:null,request});state.results.delete(op.id);const current=()=>route==='queue'&&flowTab!=='panggilan'&&state.authenticated&&epoch===sessionEpoch&&navigation===detailSequence&&flowResults.get('queue:default')===owner&&owner.request===request;render();try{const response=await api('/api/execute',{method:'POST',body:{operationId:op.id,values:{}}});if(!current())return;const rows=queueRows(response.result);if(!rows)throw new Error('Respons antrian belum sesuai format layanan. Coba perbarui.');owner.rows=rows;state.results.set(op.id,response.result);record('Antrian Daring','success',`HTTP ${response.result.status} · ${rows.length} antrian diterima`);}catch(error){if(!current())return;if(['AUTH_REQUIRED','LOGIN_REQUIRED','SESSION_EXPIRED'].includes(error.code)){sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);return;}owner.error=error.message;record('Antrian Daring','error',`${error.code||'ERROR'} · ${error.message}`);}finally{if(current()){owner.loading=false;owner.request=null;render();}}}
