document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button?.dataset.action==='lost-review-compose')lostReviewComposeClick(event);});

// Native IGb/FGb Yuridis flow; separate model, original persil ID, true review branch.
function disposeYuridis(){yuridisHost?.dispose();yuridisHost=null;}
function yuridisContext(){const profileOp=state.operations.find(op=>op.endpoint==='account/account_summary'&&ready(op)&&!write(op)),profile=profileOp?nativeAccountSummary(state.results.get(profileOp.id)):null;return {epoch:sessionEpoch,route,tab:flowTab,logoutPending,authenticated:state.authenticated,configured:state.connection.configured,loading:state.loading,operations:state.operations,favoriteOfficeId:typeof profile?.kantorId==='string'?profile.kantorId:null};}
function yuridisPage(){
 if(!yuridisHost)yuridisHost=createYuridisHost({document,getContext:yuridisContext,posts:yuridisPosts,formatDate:certificateDateDisplay,renderMap:parcelMapView,paintMaps:persilMapPaint,
  prepare:async()=>{const profile=state.operations.find(op=>op.endpoint==='account/account_summary'&&ready(op)&&!write(op));if(state.authenticated&&profile&&!nativeAccountSummary(state.results.get(profile.id)))await refreshNativeProfile(()=>route==='announcements'&&flowTab==='yuridis');},
  execute:async({operationId,values,files,confirm})=>{if(files){const form=new FormData();form.append('operationId',operationId);form.append('values',JSON.stringify(values));form.append('confirm',String(confirm===true));for(const entry of files)form.append(entry.key,entry.file);return api('/api/execute',{method:'POST',body:form});}return api('/api/execute',{method:'POST',body:{operationId,values}});},
  onRead:(kind,status)=>record('Pengumuman Yuridis','success','HTTP '+status+' · Respons '+kind+' diterima'),
  onSessionError:error=>{sessionEpoch++;clearPrivate();state.authenticated=false;state.user=null;render();toast(error.message);}
 });
 const tabs='<div class="service-tabs" role="tablist" aria-label="Jenis Pengumuman">'+flowDefinitions.announcements.tabs.map(tab=>'<button type="button" role="tab" aria-selected="'+(tab.id==='yuridis')+'" class="'+(tab.id==='yuridis'?'active':'')+'" data-action="flow-tab" data-id="'+esc(tab.id)+'">'+esc(tab.label)+'</button>').join('')+'</div>';
 return head('PENGUMUMAN','Pengumuman Yuridis','Informasi pengumuman yuridis pada kantor pertanahan.')+tabs+yuridisHost.html();
}

// Office markers use the entire original nearby snapshot. Name/facility
// filters affect the list only. No device position is manufactured here.
function disposeOfficeMap(retainCamera=true){
 const mounted=officeMapMount;officeMapMount=null;if(!mounted)return;
 if(retainCamera&&mounted.epoch===sessionEpoch&&flowResults.get('office:nearby')===mounted.owner){const camera=mounted.controller?.getCamera();if(camera)mounted.owner.mapCamera=camera;}
 mounted.controller?.destroy();
}
function officeMapView(owner){
 disposeOfficeMap();
 const serial=(owner.mapRenderSerial??0)+1;owner.mapRenderSerial=serial;
 const rows=owner.rows,epoch=sessionEpoch,navigation=detailSequence;
 queueMicrotask(()=>mountOfficeMap(owner,{rows,epoch,navigation,serial}));
 return `<section class="panel office-map" data-office-map><h2>Peta Kantor Pertanahan</h2><p class="form-hint">Marker memakai lokasi kantor dari layanan. Peta dasar OpenStreetMap merupakan penyesuaian tampilan browser.</p><div class="office-map-controls" role="group" aria-label="Kendali peta kantor">${[['in','Perbesar peta kantor','+'],['out','Perkecil peta kantor','−'],['reset','Atur ulang peta kantor','Atur ulang']].map(([action,label,text])=>`<button type="button" class="button secondary small" data-action="office-map-control" data-office-map-action="${action}" aria-label="${label}" disabled>${text}</button>`).join('')}</div><div class="office-map-stage"><div data-office-map-canvas class="office-map-canvas" role="region" aria-label="Peta lokasi Kantor Pertanahan"></div>${officeSelectedView(owner)}</div><p class="office-map-status form-hint" role="status">Memuat peta kantor…</p></section>`;
}
function mountOfficeMap(owner,context){
 const sourceCurrent=()=>route==='office'&&sessionEpoch===context.epoch&&detailSequence===context.navigation&&flowResults.get('office:nearby')===owner&&owner.rows===context.rows&&owner.mapRenderSerial===context.serial;
 if(!sourceCurrent())return;
 const canvas=$('#main [data-office-map-canvas]');if(!canvas||canvas.isConnected===false)return;
 if(officeMapMount?.canvas===canvas)return;
 disposeOfficeMap();
 const mounted={owner,epoch:context.epoch,canvas,controller:null};officeMapMount=mounted;
 const current=()=>officeMapMount===mounted&&sourceCurrent()&&canvas.isConnected!==false&&$('#main [data-office-map-canvas]')===canvas;
 try{
  const rows=Array.isArray(context.rows)?context.rows:[];
  mounted.controller=createOfficeMap(canvas,{entries:rows.map((item,index)=>({item,index})),selected:owner.selected&&rows.includes(owner.selected)?rows.indexOf(owner.selected):null,open:owner.detailOpen===true,camera:owner.mapCamera??null,sourceToken:context.rows},{libraryLoader:()=>loadMapLibrary(document),isCurrent:current,onCamera:camera=>{if(current())owner.mapCamera=camera;},onSelect:index=>{if(current())selectOfficeMapItem(index);},onClose:()=>{if(current()&&owner.detailOpen){owner.detailOpen=false;renderOffice();}}});
  void mounted.controller.ready.then(ok=>{if(!current())return;for(const button of canvas.closest('[data-office-map]').querySelectorAll('[data-action="office-map-control"]'))button.disabled=!ok;});
 }catch{if(current()){officeMapMount=null;const status=canvas.closest('[data-office-map]')?.querySelector('.office-map-status');if(status)status.textContent='Peta kantor belum dapat dimuat. Daftar kantor tetap tersedia.';}}
}
function selectOfficeMapItem(index){
 if(route!=='office'||!Number.isSafeInteger(index)||index<0)return false;
 const owner=getOfficeState();if(!Array.isArray(owner.rows)||!Object.hasOwn(owner.rows,index))return false;
 disposeOfficeMap(false);owner.selected=owner.rows[index];owner.detailOpen=true;owner.mapCamera=null;renderOffice();focusOfficeMapSelection(owner);return true;
}
function focusOfficeMapSelection(owner){
 const selected=owner.selected,epoch=sessionEpoch,navigation=detailSequence;
 queueMicrotask(()=>{if(route!=='office'||sessionEpoch!==epoch||detailSequence!==navigation||flowResults.get('office:nearby')!==owner||owner.selected!==selected||!owner.detailOpen)return;const panel=$('#main [data-office-map] .office-selected');panel?.scrollIntoView?.({block:'nearest'});panel?.querySelector('[data-action="office-close"]')?.focus({preventScroll:true});});
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action="office-map-control"]');if(!button||button.disabled||route!=='office'||!button.isConnected)return;const mounted=officeMapMount;if(!mounted||mounted.epoch!==sessionEpoch||flowResults.get('office:nearby')!==mounted.owner||button.closest('[data-office-map]')!==mounted.canvas.closest('[data-office-map]'))return;mounted.controller.control(button.dataset.officeMapAction);});
